PageReference resource = PageReference.forResource('Images');
System.assert(resource.getUrl().startsWith('/resource/'));
System.assert(resource.getUrl().endsWith('/Images'));
PageReference nested = PageReference.forResource('Images', 'icons/logo.png');
System.assert(nested.getUrl().startsWith('/resource/'));
System.assert(nested.getUrl().endsWith('/Images/icons/logo.png'));

